namespace QImage {
    /** The QImage::Format layouts with 8 bits a channel. */
    enum Format: int
    {
        case RGB32 = 4;
        case ARGB32 = 5;
        case ARGB32_PREMULTIPLIED = 6;
        case RGB888 = 13;
        /** Four bytes, red first; the fourth is ignored: opaque. */
        case RGBX8888 = 16;
        case RGBA8888 = 17;
        case RGBA8888_PREMULTIPLIED = 18;
        case BGR888 = 29;
    }
}

