    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object.
     *
     * @not-serializable
     */
    final class QImage
    {
        /**
         * QImage(data, width, height, bytesPerLine, format, cleanupFunction, cleanupInfo): Qt borrows
         * the buffer at the address $data (a QByteArray's or a framebuffer's pointer()), which must
         * outlive every image sharing it; copy() makes an image of its own. Once the last image
         * sharing the buffer goes, Qt calls $cleanupFunction($cleanupInfo), on the thread that
         * made the image. A null address or bad dimensions make Qt's null image.
         */
        public function __construct(int $data, int $width, int $height, int $bytesPerLine, QImage\Format $format, ?callable $cleanupFunction = null, mixed $cleanupInfo = null) {}

        public function isNull(): bool {}

        public function width(): int {}

        public function height(): int {}

        public function format(): QImage\Format {}

        /** $rect null is Qt's default QRect(): the whole image. */
        public function copy(?QRect $rect = null): QImage {}
    }

    /**
     * Heap item: PHP owns it until QTableWidget::setItem() hands it to a table.
     *
     * @not-serializable
     */
    final class QTableWidgetItem
    {
        /** @cvalue QTableWidgetItem::Type */
        public const int TYPE = UNKNOWN;
        /** @cvalue QTableWidgetItem::UserType */
        public const int USER_TYPE = UNKNOWN;

        public function __construct(string $text = "", int $type = QTableWidgetItem::TYPE) {}

        public function text(): string {}

        public function setText(string $text): void {}

        public function type(): int {}

        /** The item's row in its table; -1 when no table holds it. */
        public function row(): int {}
    }

    /**
     * Heap item: PHP owns it until QTreeWidget::addTopLevelItem() or addChild() hands it to a tree or a
     * parent item; its wrapper reports "deleted" once Qt deletes it (with its tree, its parent, or clear()).
     *
     * @not-serializable
     */
    final class QTreeWidgetItem
    {
        /** @cvalue QTreeWidgetItem::Type */
        public const int TYPE = UNKNOWN;
        /** @cvalue QTreeWidgetItem::UserType */
        public const int USER_TYPE = UNKNOWN;

        public function __construct(int $type = QTreeWidgetItem::TYPE) {}

        public function text(int $column): string {}

        public function setText(int $column, string $text): void {}

        public function foreground(int $column): QBrush {}

        public function setForeground(int $column, QBrush $brush): void {}

        /**
         * $role: a Qt\ItemDataRole value or a user role. The QVariant as PHP holds it: null when it holds
         * nothing; null, bool, int, float, string; Qt's value classes (QBrush, QColor, QFont, QPixmap,
         * QPoint, QSize, …) as their PHP classes; a type with no PHP class (QIcon) as null.
         */
        public function data(int $column, int $role): mixed {}

        /** $value as QVariant: null, bool, int, float, string, or one of Qt's value classes. */
        public function setData(int $column, int $role, mixed $value): void {}

        /**
         * The parent owns the child once Qt stored it; Qt ignores a child that already has a tree or a parent item.
         * Qt walks the new child's subtree with no cycle check: an item added under itself or under one of its
         * own descendants never returns.
         */
        public function addChild(QTreeWidgetItem $child): void {}

        public function childCount(): int {}

        public function child(int $index): ?QTreeWidgetItem {}

        /** Null for a top-level item, as for a loose one. */
        public function parent(): ?QTreeWidgetItem {}

        /** Read from the item's tree: false while no tree holds it. */
        public function isExpanded(): bool {}

        public function setExpanded(bool $expand): void {}

        public function childIndicatorPolicy(): QTreeWidgetItem\ChildIndicatorPolicy {}

        public function setChildIndicatorPolicy(QTreeWidgetItem\ChildIndicatorPolicy $policy): void {}
    }
}
